CREATE OR REPLACE FUNCTION public.activate_organization_operation(p_organization_id uuid) RETURNS public.organizations LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v public.organizations; BEGIN IF NOT(public.is_admin(auth.uid()) OR EXISTS(SELECT 1 FROM public.organization_members m WHERE m.organization_id=p_organization_id AND m.user_id=auth.uid() AND m.papel::text IN ('admin','manager'))) THEN RAISE EXCEPTION 'Sem permissão'; END IF; IF EXISTS(SELECT 1 FROM public.organization_implementation_steps WHERE organization_id=p_organization_id AND status<>'concluido') THEN RAISE EXCEPTION 'Conclua o playbook antes de ativar a operação'; END IF; UPDATE public.organizations SET operational_profile=coalesce(operational_profile,'{}'::jsonb)||jsonb_build_object('etapa','operacao','activated_at',now()) WHERE id=p_organization_id RETURNING * INTO v; RETURN v; END $$;
REVOKE ALL ON FUNCTION public.activate_organization_operation(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.activate_organization_operation(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.organization_common_area_metrics(p_organization_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v jsonb; BEGIN IF NOT(public.is_admin(auth.uid()) OR public.user_has_org(auth.uid(),p_organization_id)) THEN RAISE EXCEPTION 'Sem permissão'; END IF; SELECT jsonb_build_object('areas',coalesce((SELECT jsonb_agg(jsonb_build_object('area',area_type,'reservas',total,'concluidas',concluidas)) FROM (SELECT area_type,count(*) total,count(*) filter(where status='concluida') concluidas FROM public.area_reservations WHERE organization_id=p_organization_id AND starts_at>=now()-interval '30 days' GROUP BY area_type) q),'[]'::jsonb),'servicos',coalesce((SELECT jsonb_agg(jsonb_build_object('tipo',service_type,'total',total,'em_aberto',open)) FROM (SELECT service_type,count(*) total,count(*) filter(where status in('solicitada','cotada','confirmada')) open FROM public.service_requests WHERE organization_id=p_organization_id AND created_at>=now()-interval '30 days' GROUP BY service_type) q),'[]'::jsonb)) INTO v; RETURN v; END $$;
REVOKE ALL ON FUNCTION public.organization_common_area_metrics(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.organization_common_area_metrics(uuid) TO authenticated;

